import{_ as s,l as i,o as a,c as o,v as r,p as l,x as t,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"序列比对与位并行","description":"","frontmatter":{"title":"序列比对与位并行","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sequence-alignment.md","filePath":"cs/sequence-alignment.md","lastUpdated":1789023840000}'),m={name:"cs/sequence-alignment.md"};function p(u,e,_,E,f,D){const n=i("Mermaid");return a(),o("div",null,[e[1]||(e[1]=r('<h1 id="序列比对与位并行" tabindex="-1">序列比对与位并行 <a class="header-anchor" href="#序列比对与位并行" aria-label="Permalink to &quot;序列比对与位并行&quot;">​</a></h1><div class="epigraph"><p>比对是带分的编辑；Myers 用位运算把格图一列打进机器字，$O(nm/w)$ 算单位代价距离。</p><footer>—— 据 Needleman and Wunsch, 1970；Smith and Waterman, 1981；Myers, A Fast Bit-Vector Algorithm, 1999；[word RAM](/cs/word-ram) 对照整理</footer></div><p>上一课<a href="/cs/edit-distance-hirschberg">编辑距离与 Hirschberg</a>给了单位代价格图。生物比对：匹配加分、错配罚、缺口罚；全局 Needleman–Wunsch，局部 Smith–Waterman。缺口是计分矩阵与<strong>位并行</strong>：后课 word RAM 再抽象模型，本课先用。不重写 Hirschberg。本单元 DP 还剩最优 BST 与 Knuth。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NW：全局对齐两端。SW：任意子串对，DP 多一项与 0 取 max。仿射缺口：三种状态（匹配/开缺口）Gotoh \\(O(nm)\\)。单位代价 Levenshtein 可用 Myers：把 \\(\\Delta\\) 编码成位向量，沿模式预处理，文本扫描 \\(O(nm/w)\\)。</p><p>缺口是计分与字并行，不是新的最优子结构。</p><h3 id="不是-transformer-注意力" tabindex="-1">不是 Transformer 注意力 <a class="header-anchor" href="#不是-transformer-注意力" aria-label="Permalink to &quot;不是 Transformer 注意力&quot;">​</a></h3><p>序列对齐是 DP 格图，不是注意力权重。本课 CS 算法，不写神经网络对齐。</p><p><span class="marginnote">Needleman–Wunsch 1970。Smith–Waterman 1981。Myers 1999 bit-vector。后课最优 BST 回到树形区间 DP。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>NW/SW 填表。需要路径则前驱或 Hirschberg 变体。单位距离用 Myers 位向量。长序列启发式（BLAST）点名，不保证最优。</p>',11)),(a(),l(c,null,{default:t(()=>[h(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NW%5B%22%E5%85%A8%E5%B1%80%20NW%22%5D%20--%3E%20GRD%5B%22%E8%AE%A1%E5%88%86%E6%A0%BC%E5%9B%BE%22%5D%0A%20%20SW%5B%22%E5%B1%80%E9%83%A8%20SW%22%5D%20--%3E%20GRD%0A%20%20MY%5B%22Myers%20%E4%BD%8D%E5%90%91%E9%87%8F%22%5D%20--%3E%20LEV%5B%22%E5%8D%95%E4%BD%8D%E7%BC%96%E8%BE%91%E8%B7%9D%E7%A6%BB%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>字母表小利于位掩码预处理。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SW 的 \\(0\\) 截断对应「重新开始」。Myers：水平/垂直差的进位用字内移位模拟格图依赖。与 KMP：KMP 精确无误差；比对允许误差。与 FFT：卷积可做无缺口打分，缺口仍 DP。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写多序列比对（NPC）。不写隐马尔可夫 profile。后课默认：全局/局部比对是带分 DP；单位距离可位并行。下一课最优二叉搜索树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NW 全局、SW 局部；仿射缺口三状态。</li><li>Myers 把单位距离做到 \\(O(nm/w)\\)。</li><li>启发式检索不是精确 DP。</li><li>出处：Needleman and Wunsch, 1970；Smith and Waterman, 1981；Myers, 1999。</li></ul>',7))])}const P=s(m,[["render",p]]);export{S as __pageData,P as default};
